-- AXO-202: eval cases for the scheme_check stage (prompt scheme_check.v1), so the prompt gate has a
-- real passing eval run behind the prompt instead of an unevaluated file.
--
-- Generated from evals/golden/scheme-check-v1.json (build_scheme_check_v1.py). Every question,
-- student answer and scheme section is invented for this eval: no Cambridge or Pearson scheme text,
-- no student data. Expected estimates are DRAFT labels until the owner confirms them.

alter table public.eval_case drop constraint if exists eval_case_stage_check;
alter table public.eval_case add constraint eval_case_stage_check check (stage in ('explain', 'topic_tag', 'scheme_check'));

on conflict (id) do nothing;
